import{_ as l,C as a,c as i,o as p,j as o,G as t,ak as c,a as d}from"./chunks/framework.D7ejh1zC.js";const _="/assets/%E7%94%A8%E9%87%8F%E8%B4%B9%E7%94%A8.Dl_uMiro.png",m="/assets/%E6%A8%A1%E5%9E%8BAPI%E5%8F%82%E8%80%83.Bz4N8guP.png",A="/assets/%E8%B0%83%E8%AF%95%E7%BB%93%E6%9E%9C.C35Qtron.png",k=JSON.parse('{"title":"购买调试大模型 API","description":"","frontmatter":{},"headers":[],"relativePath":"ai/第二章 AI Agent 工程基础/调试大模型 API.md","filePath":"practice/ai/AI Agent+智能大屏设计器/第二章 AI Agent 工程基础/调试大模型 API.md","lastUpdated":1787235005000}'),h={name:"ai/第二章 AI Agent 工程基础/调试大模型 API.md"};function g(u,e,P,I,b,f){const s=a("mdInfo"),n=a("NolebaseGitContributors"),r=a("NolebaseGitChangelog");return p(),i("div",null,[e[0]||(e[0]=o("h1",{id:"购买调试大模型-api",tabindex:"-1"},[d("购买调试大模型 API "),o("a",{class:"header-anchor",href:"#购买调试大模型-api","aria-label":'Permalink to "购买调试大模型 API"'},"​")],-1)),t(s),e[1]||(e[1]=c('<h2 id="登录" tabindex="-1">登录 <a class="header-anchor" href="#登录" aria-label="Permalink to &quot;登录&quot;">​</a></h2><p>先打开这个网站：<a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">阿里百炼</a> 登录。</p><p>类似的模型购买平台有很多，比如 硅基流动、 deepseek，不一一介绍了，我们的课程就使用 阿里百炼。</p><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><p>左上角 nav 菜单点击“模型”，左下角点击“用量&amp;费用”。</p><p><img src="'+_+'" alt="用量费用" loading="lazy"></p><p>查看是否有免费额度，如果有可以免费使用；没有则需要点击右上角头像，选择“充值汇款”购买。</p><p>充值完或者有免费不需要充值，返回上一页模块，点击“API key”，右上角点击“创建API key”按钮，描述随意，然后<strong>不要关闭弹窗，后续无法再重新打开，建议截图保存并复制一份保存到文档里</strong>。</p><h2 id="调试" tabindex="-1">调试 <a class="header-anchor" href="#调试" aria-label="Permalink to &quot;调试&quot;">​</a></h2><p>然后关闭弹窗，点击上方nav菜单的“API 参考”，点击左侧的“OpenAI兼容-Chat”，还可以调试，只需要粘贴刚刚保存的 API key即可。</p><p><img src="'+m+'" alt="模型API参考" loading="lazy"></p><p>请求体已经配置好了，其中：</p><ul><li>model：模型名称，这里使用的是 <code>qwen-plus</code>。</li><li>messages：消息列表，发送给模型的消息。 <ul><li>role：用户角色，<code>system</code>是系统， <code>user</code> 是用户角色。</li><li>content：用户的消息。</li></ul></li></ul><p>点击发送请求后就可查看调试结果。</p><p><img src="'+A+'" alt="调试结果" loading="lazy"></p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>要值得注意的是，大模型 是没有记忆功能的。每一次的对话都是独立的，大模型是不会记住之前的对话内容的。</p><p>那么之前使用的 deepseek、豆包都是怎么记住的呢？</p><p>其实是通过<strong>上下文传递</strong>的方式实现的。每次用户发送消息时，都会把之前的对话内容也保存到 <code>message</code> 数组里传递给模型，模型会根据历史消息上下文来生成回复。</p><p>还能切换其他模型来做测试，这里不做过多赘述。</p><p>后续还能体验图片输入（注意图片路径不能去谷歌搜索），工具调用等功能。</p>',21)),t(n),t(r)])}const C=l(h,[["render",g]]);export{k as __pageData,C as default};
